"use client";

import { loadFont as loadZenKaku } from "@remotion/google-fonts/ZenKakuGothicNew";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_TEXT,
  type TategakiTurnElementId,
  tategakiTurnTimeline,
  wordsOf,
} from "./timeline";

const kaku = loadZenKaku("normal", { weights: ["500"], subsets: ["latin"] });

export interface TategakiTurnProps {
  text?: string;
  highlight?: number;
  hold?: number;
  /** Frames between words dropping into their columns. */
  stagger?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the text. Load it yourself; Zen Kaku Gothic New by default. */
  fontFamily?: string;
  /** Size of the text, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single words and the turn, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<TategakiTurnElementId>;
}

const VERMILION = "#E03C31";

const THEMES = {
  dark: { bg: "#111111", ink: "#F5F1EA" },
  light: { bg: "#F5F1EA", ink: "#111111" },
} as const;

const TRACK = -0.02;
const PITCH = 1.2;
const STRETCH = 0.22;
const COL = 1.34;

const DROP = 0.42;
const LINE = 1.16;
const TIER_GAP = 0.9;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_TRAVEL = Easing.bezier(0.45, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface WordMetrics {
  chars: string[];
  lefts: number[];
  advs: number[];
  width: number;
}

interface Metrics {
  words: WordMetrics[];
  space: number;
  cap: number;
  base: number;
  colW: number;
}

function measure(words: string[], fontFamily: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("tategaki-turn: no 2d context");
  ctx.font = `500 100px "${fontFamily}"`;
  const w = (s: string) => ctx.measureText(s).width / 100;
  const h = ctx.measureText("H");
  const asc = h.fontBoundingBoxAscent / 100;
  const desc = h.fontBoundingBoxDescent / 100;
  let colW = 0;
  const out = words.map((word) => {
    const chars = Array.from(word);
    const lefts = chars.map(
      (_c, k) => w(chars.slice(0, k).join("")) + TRACK * k,
    );
    const advs = chars.map((ch) => {
      const a = w(ch);
      colW = Math.max(colW, a);
      return a;
    });
    return {
      chars,
      lefts,
      advs,
      width: w(word) + TRACK * Math.max(0, chars.length - 1),
    };
  });
  return {
    words: out,
    space: w(" "),
    cap: h.actualBoundingBoxAscent / 100,
    base: (1 - (asc + desc)) / 2 + asc,
    colW,
  };
}

function useMetrics(words: string[], fontFamily: string) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("tategaki-turn: measuring"));
  const released = useRef(false);
  const key = JSON.stringify(words);
  useEffect(() => {
    let live = true;
    Promise.all([
      kaku.waitUntilDone(),
      document.fonts.load(`500 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(JSON.parse(key) as string[], fontFamily));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, fontFamily, handle]);
  return metrics;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function TategakiTurn(props: TategakiTurnProps) {
  const {
    text = DEFAULT_TEXT,
    highlight,
    accent,
    ink,
    background,
    fontFamily = kaku.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    tategakiTurnTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const bg = background ?? c.bg;
  const red = accent ?? VERMILION;

  const words = useMemo(() => wordsOf(text), [text]);
  const m = useMetrics(words, fontFamily);

  if (!m) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const n = m.words.length;
  const hiIdx = highlight ?? n - 1;
  const pitch = m.cap * PITCH;
  const colPitch = Math.max(m.colW, m.cap) * COL;
  const portrait = H > W;
  const fitW = W * (portrait ? 0.88 : 0.86);
  const widths = m.words.map((wd) => wd.width);
  const lineW = (ids: number[]) =>
    ids.reduce((acc, j) => acc + widths[j], 0) +
    m.space * Math.max(0, ids.length - 1);
  const greedy = (maxW: number) => {
    const out: number[][] = [];
    let cur: number[] = [];
    for (let j = 0; j < n; j++) {
      if (cur.length && lineW([...cur, j]) > maxW) {
        out.push(cur);
        cur = [j];
      } else cur.push(j);
    }
    if (cur.length) out.push(cur);
    return out;
  };
  const breakInto = (L: number) => {
    let lo = Math.max(...widths);
    let hi = lineW(m.words.map((_wd, j) => j));
    for (let i = 0; i < 30; i++) {
      const mid = (lo + hi) / 2;
      if (greedy(mid).length <= L) hi = mid;
      else lo = mid;
    }
    return greedy(hi);
  };
  const finalSize = (ls: number[][]) =>
    Math.min(
      fitW / Math.max(...ls.map(lineW)),
      H * 0.26,
      (H * 0.72) / (m.cap + (ls.length - 1) * LINE),
    );
  const maxLines = Math.min(n, portrait ? 3 : 2);
  let lines = breakInto(1);
  let best = { ls: lines, f: finalSize(lines) };
  for (let L = 1; L <= maxLines; L++) {
    const ls = breakInto(L);
    const f = finalSize(ls);
    if (f > best.f) best = { ls, f };
    if (f >= Math.min(W, H) * (portrait ? 0.17 : 0.12)) {
      best = { ls, f };
      break;
    }
  }
  lines = best.ls;
  const Fh = best.f;

  const lineOf: number[] = [];
  const wordX: number[] = [];
  const wordY: number[] = [];
  lines.forEach((ids, l) => {
    let x = 0;
    for (const j of ids) {
      lineOf[j] = l;
      wordX[j] = x;
      wordY[j] = l * LINE;
      x += widths[j] + m.space;
    }
  });
  const hCenter = (j: number, k: number) =>
    wordX[j] + m.words[j].lefts[k] + m.words[j].advs[k] / 2;

  const pivotV: { x: number; y: number }[] = [];
  let tierY = 0;
  let maxCols = 1;
  lines.forEach((ids, l) => {
    const longest = Math.max(...ids.map((j) => m.words[j].chars.length));
    maxCols = Math.max(maxCols, ids.length);
    ids.forEach((j, i) => {
      pivotV[j] = { x: (i - (ids.length - 1) / 2) * colPitch, y: tierY };
    });
    if (l < lines.length - 1) tierY += (longest - 1) * pitch + TIER_GAP + m.cap;
    else tierY += (longest - 1) * pitch;
  });
  const stageH = tierY + m.cap;
  const Fv = Math.min(
    (H * 0.84) / stageH,
    fitW / (maxCols * colPitch),
    H * (portrait ? 0.16 : 0.22),
  );

  const turn = tl.get("turn");
  const turnAt = turn.start;
  const wordEls = m.words.map((_wd, j) => tl.get(`word:${j}`));

  interface Glyph {
    j: number;
    k: number;
    ch: string;
    x: number;
    y: number;
    adv: number;
  }
  // Every glyph's box and font size at `time`. Called for the neighbouring
  // frames and for the settled line, so the travel can be a transform.
  const sceneAt = (time: number) => {
    const swing = m.words.map((_wd, j) =>
      spring({
        frame: time - turnAt - lineOf[j] * turn.beat("line"),
        fps,
        durationInFrames: turn.beat("swing"),
        config: { damping: 15, stiffness: 90, mass: 1 },
      }),
    );
    const travel = m.words.map((_wd, j) => {
      const s0 = turnAt + lineOf[j] * turn.beat("line");
      return interpolate(
        time,
        [s0 + turn.beat("travelLead"), s0 + turn.beat("travel")],
        [0, 1],
        { ...CLAMP, easing: EASE_TRAVEL },
      );
    });
    const zoomP =
      travel.reduce((acc, v) => acc + v, 0) / Math.max(1, travel.length);

    const glyphs: Glyph[] = [];
    m.words.forEach((wd, j) => {
      const ph = { x: hCenter(j, 0), y: wordY[j] };
      const pv = pivotV[j];
      const theta = (Math.PI / 2) * (1 - swing[j]);
      const px = pv.x + (ph.x - pv.x) * travel[j];
      const py = pv.y + (ph.y - pv.y) * travel[j];
      const bend = Math.min(Math.PI / 2, Math.max(0, theta));
      const g = 1 + STRETCH * Math.sin(2 * bend);
      const cos = Math.cos(theta);
      wd.chars.forEach((ch, k) => {
        const rv = k * pitch;
        const rh = hCenter(j, k) - ph.x;
        let d = g * Math.hypot(rh * cos, rv * Math.sin(theta));
        if (cos > 0.001) d = Math.min(d, rh / cos);
        glyphs.push({
          j,
          k,
          ch,
          x: px + d * cos,
          y: py + d * Math.sin(theta),
          adv: wd.advs[k],
        });
      });
    });

    let minX = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let minY = Number.POSITIVE_INFINITY;
    let maxY = Number.NEGATIVE_INFINITY;
    for (const g of glyphs) {
      minX = Math.min(minX, g.x - g.adv / 2);
      maxX = Math.max(maxX, g.x + g.adv / 2);
      minY = Math.min(minY, g.y - m.cap);
      maxY = Math.max(maxY, g.y);
    }
    const F = Math.min(
      Fv + (Fh - Fv) * zoomP,
      fitW / (maxX - minX),
      (H * 0.84) / (maxY - minY),
    );
    const marginX = W * (portrait ? 0.08 : 0.07);
    const marginY = H * (portrait ? 0.07 : 0.09);
    const oxV = W - marginX - maxX * F;
    const oyV = marginY - minY * F;
    const oxH = marginX - minX * F;
    const oyH = H - marginY - maxY * F;
    const ox = oxV + (oxH - oxV) * zoomP;
    const oy = oyV + (oyH - oyV) * zoomP;

    return glyphs.map((g) => {
      const word = wordEls[g.j];
      const startAt = word.start + g.k * word.beat("letter");
      const rise = interpolate(
        time,
        [startAt, startAt + word.beat("rise")],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      return {
        ...g,
        rise,
        F,
        left: ox + (g.x - g.adv / 2) * F,
        top: oy + (g.y - m.base) * F,
        drop: -(1 - rise) * DROP * F,
      };
    });
  };

  // Layout rounds a box and a baseline to whole pixels, so a glyph eased by
  // `left`, `top` and `fontSize` steps along pixel by pixel. Each glyph is
  // laid out once, where it finally rests in the settled line, and carried by
  // a transform all its life: handing it from one layout place to another
  // would snap it by the rounding difference on that frame.
  const now = sceneAt(t);
  const before = sceneAt(t - speed);
  const after = sceneAt(t + speed);
  const settled = sceneAt(turnAt + 1e4);
  const moved = (i: number) =>
    [before[i], after[i]].some(
      (o) =>
        Math.abs(o.left - now[i].left) > 1e-3 ||
        Math.abs(o.top + o.drop - now[i].top - now[i].drop) > 1e-3 ||
        Math.abs(o.F - now[i].F) * 1.4 > 1e-3,
    );

  const nodes: React.ReactNode[] = now.map((g, i) => {
    const fill: React.CSSProperties = { color: g.j === hiIdx ? red : fg };
    const rest = settled[i];
    const off = (v: number) => (Math.abs(v) < 1e-3 ? 0 : v);
    const dx = off(g.left - rest.left);
    const dy = off(g.top + g.drop - rest.top);
    const k = Math.abs(g.F / rest.F - 1) < 1e-6 ? 1 : g.F / rest.F;
    return (
      <div
        key={`${g.j}-${g.k}`}
        style={{
          position: "absolute",
          left: rest.left,
          top: rest.top,
          width: g.adv * rest.F,
          height: rest.F * 1.4,
          opacity: g.rise,
          fontFamily,
          fontWeight: 500,
          fontSize: rest.F,
          lineHeight: `${rest.F}px`,
          textAlign: "center",
          whiteSpace: "pre",
          transformOrigin: "0 0",
          transform: `translate(${dx}px, ${dy}px) scale(${k})${glide(moved(i))}`,
          ...fill,
        }}
      >
        {g.ch}
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{nodes}</ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// Each word dropping letter by letter into its vertical column, then the turn:
// every line swinging from vertical to horizontal and travelling to its place
// in the settled line. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

export type TategakiTurnElementId = `word:${number}` | "turn";

export interface TategakiTurnTimingProps {
  text?: string;
  hold?: number;
  stagger?: number;
}

export const DEFAULT_TEXT = "Read it both ways.";
export const COL_STAGGER = 5;
const DEFAULT_HOLD = 16;

const LETTER_STAGGER = 2;
const LETTER_LEN = 11;
/** A word's first letter starts this many frames before its slot. */
const LETTER_LEAD = 3;
const SWING_LEN = 36;
const LINE_STAGGER = 12;
const TRAVEL_LEAD = 2;
const TRAVEL_LEN = 22;

/** The words of `text`; a blank text is one blank word. */
export function wordsOf(text: string) {
  const ws = text.split(/\s+/).filter(Boolean);
  return ws.length ? ws : [" "];
}

// `word:<j>` runs from its first letter starting to its last letter landing;
// the `letter` beat is the gap between letters, `rise` one letter's drop. The
// words form a chain. The turn follows the last word: line `l` starts
// swinging `l` × `line` frames after it, its `swing` spring lasts `swing`
// frames, and it travels from `travelLead` to `travel` frames after its own
// start. Which line a word sits on is measured, so the line offset is applied
// in the component.
export const tategakiTurnTimeline = defineTimeline<
  TategakiTurnElementId,
  TategakiTurnTimingProps
>(({ text = DEFAULT_TEXT, hold = DEFAULT_HOLD, stagger = COL_STAGGER }) => {
  const words = wordsOf(text);
  const n = words.length;
  const maxLen = Math.max(1, ...words.map((w) => Array.from(w).length));
  const lastStart = (n - 1) * stagger + (maxLen - 1) * LETTER_STAGGER;
  const turnAt = lastStart + LETTER_LEN + hold;
  const elements: TimelineElement<TategakiTurnElementId>[] = words.map(
    (word, j): TimelineElement<TategakiTurnElementId> => ({
      id: `word:${j}`,
      lane: "Words",
      label: word,
      start: j * stagger - LETTER_LEAD,
      length: (Array.from(word).length - 1) * LETTER_STAGGER + LETTER_LEN,
      follows: j > 0 ? `word:${j - 1}` : undefined,
      beats: { letter: LETTER_STAGGER, rise: LETTER_LEN },
    }),
  );
  elements.push({
    id: "turn",
    lane: "Turn",
    label: "turn",
    start: turnAt,
    length: SWING_LEN,
    follows: `word:${n - 1}`,
    beats: {
      line: LINE_STAGGER,
      swing: SWING_LEN,
      travelLead: -TRAVEL_LEAD,
      travel: TRAVEL_LEN,
    },
  });
  return elements;
});
